<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Farming Game</title>
    <style>
        canvas {
            border: 1px solid black;
        }
    </style>
</head>
<body>
    <canvas id="gameCanvas" width="800" height="600"></canvas>
    <script>
        const canvas = document.getElementById('gameCanvas');
        const ctx = canvas.getContext('2d');

        // Game state
        let player = { x: 0, y: 0 };
        let tiles = {};
        let inventory = { seeds: 10, crops: 0 };
        let day = 0;

        // Game loop
        function gameLoop() {
            requestAnimationFrame(gameLoop);

            // Update game state
            player.x += (event.key === 'ArrowRight') ? 1 : (event.key === 'ArrowLeft') ? -1 : 0;
            player.y += (event.key === 'ArrowDown') ? 1 : (event.key === 'ArrowUp') ? -1 : 0;

            // Plant seed
            if (event.key === 'p') {
                const seed = { crop: 'corn', stage: 0 };
                tiles[player.x + ',' + player.y] = seed;
                inventory.seeds--;
            }

            // Harvest crop
            if (event.key === 'h') {
                if (tiles[player.x + ',' + player.y] && tiles[player.x + ',' + player.y].crop === 'corn' && tiles[player.x + ',' + player.y].stage === 3) {
                    tiles[player.x + ',' + player.y] = null;
                    inventory.crops++;
                }
            }

            // Update tile stages
            for (const tile in tiles) {
                if (tiles[tile]) {
                    tiles[tile].stage++;
                    if (tiles[tile].stage === 3) {
                        tiles[tile] = null;
                    }
                }
            }

            // Draw tiles
            ctx.clearRect(0, 0, canvas.width, canvas.height);
            for (const tile in tiles) {
                if (tiles[tile]) {
                    ctx.fillStyle = tiles[tile].crop === 'corn' ? 'green' : 'red';
                    ctx.fillRect(tile.split(',')[0], tile.split(',')[1], 1, 1);
                }
            }

            // Update day
            day++;
        }

        // Save game to localStorage
        function saveGame() {
            localStorage.setItem('game', JSON.stringify({ player, tiles, inventory, day }));
        }

        // Load game from localStorage
        function loadGame() {
            const savedGame = localStorage.getItem('game');
            if (savedGame) {
                const state = JSON.parse(savedGame);
                player = state.player;
                tiles = state.tiles;
                inventory = state.inventory;
                day = state.day;
            }
        }

        // Event listeners
        document.addEventListener('keydown', (event) => {
            if (event.key === 'p' || event.key === 'h') {
                event.preventDefault();
            }
        });

        // Game loop
        gameLoop();

        // Save game on window load
        window.addEventListener('load', saveGame);

        // Load game on page load
        loadGame();
    </script>
</body>
</html>
